arguments.file_text:
@page "/settings"
@using sv_7176710e9212444a8ba7c8673b33d164.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(ActiveSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(ActiveSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(ActiveSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(ActiveSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (IsLoading)
        {
            <div class="loading">Loading...</div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "Profile":
                    @RenderProfile()
                    break;
                case "Notifications":
                    @RenderNotifications()
                    break;
                case "Security":
                    @RenderSecurity()
                    break;
                case "Appearance":
                    @RenderAppearance()
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(ToastMessage))
        {
            <div class="toast @ToastType">
                @ToastMessage
            </div>
        }
    </main>
</div>

@if (ShowRevokeConfirmation)
{
    <div class="modal-overlay" @onclick="CancelRevoke">
        <div class="modal" @onclick:stopPropagation="true">
            <h3>Revoke Session</h3>
            <p>Are you sure you want to revoke this session? The device will be signed out immediately.</p>
            <div class="modal-actions">
                <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                <button class="btn btn-danger" @onclick="ConfirmRevoke">Revoke</button>
            </div>
        </div>
    </div>
}

@code {
    private string ActiveSection { get; set; } = "Profile";
    private bool IsLoading { get; set; } = true;
    private string? ToastMessage { get; set; }
    private string ToastType { get; set; } = "success";

    // Profile state
    private string ProfileDisplayName { get; set; } = "";
    private string ProfileEmail { get; set; } = "";
    private string ProfileAvatarUrl { get; set; } = "";
    private string ProfileBio { get; set; } = "";
    private UserProfile? _savedProfile;

    // Notification state
    private bool NotifEmail { get; set; }
    private bool NotifPush { get; set; }
    private bool NotifWeeklyDigest { get; set; }
    private List<ChannelMuteState> Channels { get; set; } = new();

    // Security state
    private SecuritySettings? SecurityData { get; set; }
    private bool ChangePasswordExpanded { get; set; }
    private string CurrentPassword { get; set; } = "";
    private string NewPassword { get; set; } = "";
    private string ConfirmPassword { get; set; } = "";
    private bool ShowRevokeConfirmation { get; set; }
    private string? SessionToRevoke { get; set; }

    // Appearance state
    private string SelectedTheme { get; set; } = "Light";
    private string SelectedFontSize { get; set; } = "Medium";
    private string SelectedLanguage { get; set; } = "English";
    private bool CompactMode { get; set; }

    private static readonly string[] AvailableLanguages = { "English", "Spanish", "French", "German", "Japanese", "Chinese" };

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionData();
    }

    private async Task SetSection(string section)
    {
        ActiveSection = section;
        IsLoading = true;
        await LoadSectionData();
    }

    private async Task LoadSectionData()
    {
        switch (ActiveSection)
        {
            case "Profile":
                var profile = await SettingsService.GetProfileAsync();
                _savedProfile = profile;
                ProfileDisplayName = profile.DisplayName;
                ProfileEmail = profile.Email;
                ProfileAvatarUrl = profile.AvatarUrl;
                ProfileBio = profile.Bio;
                break;
            case "Notifications":
                var prefs = await SettingsService.GetNotificationPrefsAsync();
                NotifEmail = prefs.EmailNotifications;
                NotifPush = prefs.PushNotifications;
                NotifWeeklyDigest = prefs.WeeklyDigest;
                Channels = prefs.MutedChannels.Select(c => new ChannelMuteState(c, true)).ToList();
                break;
            case "Security":
                SecurityData = await SettingsService.GetSecuritySettingsAsync();
                ChangePasswordExpanded = false;
                CurrentPassword = "";
                NewPassword = "";
                ConfirmPassword = "";
                break;
            case "Appearance":
                var appearance = await SettingsService.GetAppearanceAsync();
                SelectedTheme = appearance.Theme;
                SelectedFontSize = appearance.FontSize;
                SelectedLanguage = appearance.Language;
                CompactMode = appearance.CompactMode;
                break;
        }
        IsLoading = false;
    }

    private async Task SaveProfile()
    {
        var profile = new UserProfile(ProfileDisplayName, ProfileEmail, ProfileAvatarUrl, ProfileBio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        await ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
        {
            ProfileDisplayName = _savedProfile.DisplayName;
            ProfileEmail = _savedProfile.Email;
            ProfileAvatarUrl = _savedProfile.AvatarUrl;
            ProfileBio = _savedProfile.Bio;
        }
    }

    private async Task SaveNotifications()
    {
        var mutedChannels = Channels.Where(c => c.IsMuted).Select(c => c.Name).ToList();
        var prefs = new NotificationPrefs(NotifEmail, NotifPush, NotifWeeklyDigest, mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        await ShowToast("Notification preferences saved!", "success");
    }

    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(CurrentPassword) || string.IsNullOrWhiteSpace(NewPassword))
        {
            await ShowToast("Please fill in all password fields.", "error");
            return;
        }
        if (NewPassword != ConfirmPassword)
        {
            await ShowToast("New passwords do not match.", "error");
            return;
        }
        await SettingsService.ChangePasswordAsync(CurrentPassword, NewPassword);
        CurrentPassword = "";
        NewPassword = "";
        ConfirmPassword = "";
        ChangePasswordExpanded = false;
        SecurityData = await SettingsService.GetSecuritySettingsAsync();
        await ShowToast("Password updated successfully!", "success");
    }

    private void RequestRevoke(string sessionId)
    {
        SessionToRevoke = sessionId;
        ShowRevokeConfirmation = true;
    }

    private void CancelRevoke()
    {
        ShowRevokeConfirmation = false;
        SessionToRevoke = null;
    }

    private async Task ConfirmRevoke()
    {
        if (SessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(SessionToRevoke);
            SecurityData = await SettingsService.GetSecuritySettingsAsync();
            await ShowToast("Session revoked.", "success");
        }
        ShowRevokeConfirmation = false;
        SessionToRevoke = null;
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(SelectedTheme, SelectedFontSize, SelectedLanguage, CompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        await ShowToast("Appearance settings saved!", "success");
    }

    private async Task ShowToast(string message, string type)
    {
        ToastMessage = message;
        ToastType = type;
        StateHasChanged();
        await Task.Delay(3000);
        ToastMessage = null;
        StateHasChanged();
    }

    private RenderFragment RenderProfile() => __builder =>
    {
        <section class="settings-section">
            <h2>Profile</h2>

            <div class="avatar-area">
                <div class="avatar-preview">
                    <img src="@ProfileAvatarUrl" alt="Avatar" />
                </div>
                <div class="avatar-url">
                    <label>Avatar URL</label>
                    <input type="text" @bind="ProfileAvatarUrl" />
                </div>
            </div>

            <div class="form-group">
                <label>Display Name</label>
                <input type="text" @bind="ProfileDisplayName" />
            </div>

            <div class="form-group">
                <label>Email</label>
                <input type="email" @bind="ProfileEmail" />
            </div>

            <div class="form-group">
                <label>Bio</label>
                <textarea rows="4" @bind="ProfileBio"></textarea>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>
    };

    private RenderFragment RenderNotifications() => __builder =>
    {
        <section class="settings-section">
            <h2>Notifications</h2>

            <div class="toggle-group">
                <label class="toggle-label">
                    <span>Email Notifications</span>
                    <label class="switch">
                        <input type="checkbox" @bind="NotifEmail" />
                        <span class="slider"></span>
                    </label>
                </label>

                <label class="toggle-label">
                    <span>Push Notifications</span>
                    <label class="switch">
                        <input type="checkbox" @bind="NotifPush" />
                        <span class="slider"></span>
                    </label>
                </label>

                <label class="toggle-label">
                    <span>Weekly Digest</span>
                    <label class="switch">
                        <input type="checkbox" @bind="NotifWeeklyDigest" />
                        <span class="slider"></span>
                    </label>
                </label>
            </div>

            <h3>Muted Channels</h3>
            <div class="channel-list">
                @foreach (var channel in Channels)
                {
                    <label class="channel-item">
                        <input type="checkbox" @bind="channel.IsMuted" />
                        <span>#@channel.Name</span>
                    </label>
                }
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </section>
    };

    private RenderFragment RenderSecurity() => __builder =>
    {
        <section class="settings-section">
            <h2>Security</h2>

            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => ChangePasswordExpanded = !ChangePasswordExpanded">
                    <span>Change Password</span>
                    <span class="expand-icon">@(ChangePasswordExpanded ? "▼" : "▶")</span>
                </button>
                @if (ChangePasswordExpanded)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label>Current Password</label>
                            <input type="password" @bind="CurrentPassword" />
                        </div>
                        <div class="form-group">
                            <label>New Password</label>
                            <input type="password" @bind="NewPassword" />
                        </div>
                        <div class="form-group">
                            <label>Confirm New Password</label>
                            <input type="password" @bind="ConfirmPassword" />
                        </div>
                        <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                    </div>
                }
            </div>

            @if (SecurityData is not null)
            {
                <div class="toggle-group" style="margin-top: 1.5rem;">
                    <label class="toggle-label">
                        <span>
                            Two-Factor Authentication
                            <span class="status-badge @(SecurityData.TwoFactorEnabled ? "enabled" : "disabled")">
                                @(SecurityData.TwoFactorEnabled ? "Enabled" : "Disabled")
                            </span>
                        </span>
                        <label class="switch">
                            <input type="checkbox" checked="@SecurityData.TwoFactorEnabled" disabled />
                            <span class="slider"></span>
                        </label>
                    </label>
                </div>

                @if (SecurityData.LastPasswordChange.HasValue)
                {
                    <p class="meta-info">Last password change: @SecurityData.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                }

                <h3>Active Sessions</h3>
                <div class="sessions-table-wrapper">
                    <table class="sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th></th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in SecurityData.Sessions)
                            {
                                var isCurrent = session == SecurityData.Sessions.FirstOrDefault();
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td>
                                        @if (isCurrent)
                                        {
                                            <span class="current-badge">Current</span>
                                        }
                                        else
                                        {
                                            <button class="btn btn-danger btn-sm" @onclick="() => RequestRevoke(session.Id)">Revoke</button>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            }
        </section>
    };

    private RenderFragment RenderAppearance() => __builder =>
    {
        <section class="settings-section">
            <h2>Appearance</h2>

            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <label class="radio-label">
                            <input type="radio" name="theme" value="@theme" checked="@(SelectedTheme == theme)" @onchange="() => SelectedTheme = theme" />
                            @theme
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <label class="radio-label">
                            <input type="radio" name="fontSize" value="@size" checked="@(SelectedFontSize == size)" @onchange="() => SelectedFontSize = size" />
                            @size
                        </label>
                    }
